package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	char       byte
	index      int
	nextArray  [26]*Node
	hasCul     bool
	isSame     bool
	nextCount  int
	nextList   []*Node
	countArray []int64
}

func NewNode(char byte, index int, n int) *Node {
	return &Node{
		char:       char,
		index:      index,
		countArray: make([]int64, n),
	}
}

func (node *Node) addNext(idx int, other *Node) {
	if node.nextArray[idx] == nil {
		node.nextCount++
		node.nextArray[idx] = other
		node.nextList = append(node.nextList, other)
	}
}

func find(node *Node) {
	if node.hasCul {
		return
	}

	node.countArray[0]++
	for _, next := range node.nextList {
		find(next)
		for i := 0; i < len(next.countArray); i++ {
			if next.countArray[i] > 0 {
				node.countArray[i+1] += next.countArray[i]
			}
		}
	}

	node.hasCul = true
}

var reader *bufio.Reader
var writer *bufio.Writer

func readInt() int {
	n := 0
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := false
	if c == '-' {
		neg = true
		c, _ = reader.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readLong() int64 {
	var n int64 = 0
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := false
	if c == '-' {
		neg = true
		c, _ = reader.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int64(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readString() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var sb []byte
	for err == nil && c != ' ' && c != '\n' && c != '\r' && c != '\t' {
		sb = append(sb, c)
		c, err = reader.ReadByte()
	}
	return string(sb)
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	n := readInt()
	k := readLong()
	str := readString()

	var letters [26]bool
	list := make([]*Node, 0, n)
	for i := 0; i < len(str); i++ {
		char := str[i]
		node := NewNode(char, i, n)
		if letters[char-'a'] {
			node.isSame = true
		} else {
			letters[char-'a'] = true
		}
		list = append(list, node)
	}

	for i := 0; i < len(list); i++ {
		ai := list[i]
		for j := i + 1; j < len(list); j++ {
			aj := list[j]
			ai.addNext(int(aj.char-'a'), aj)
		}
	}

	for _, node := range list {
		find(node)
	}

	totalCountArray := make([]int64, n)
	for i := 0; i < n; i++ {
		for _, node := range list {
			if !node.isSame {
				totalCountArray[i] += node.countArray[i]
			}
		}
	}

	var totalCost int64 = 0
	var selectCount int64 = 0
	for i := n - 1; i >= 0; i-- {
		if selectCount+totalCountArray[i] < k {
			totalCost += int64(n-1-i) * totalCountArray[i]
			selectCount += totalCountArray[i]
		} else {
			over := (selectCount + totalCountArray[i]) - k
			totalCost += int64(n-1-i) * (totalCountArray[i] - over)
			selectCount += totalCountArray[i] - over
			break
		}
	}

	if selectCount < k {
		if selectCount == k-1 {
			fmt.Fprintln(writer, totalCost+int64(n))
		} else {
			fmt.Fprintln(writer, -1)
		}
	} else {
		fmt.Fprintln(writer, totalCost)
	}
}
